List<String> fn0(String logLine) {
  final List<String> result = [];
  if (logLine.isEmpty) return result;

  for (final token in logLine.split(',')) {
    if (token.isEmpty) continue;
    int state = 0; 
    String? sensorId;
    String? rssi;
    bool valid = true;

    for (int i = 0; i < token.length; i++) {
      final ch = token[i];
      if (state == 0) {
        if (!ch.codeUnitAt(0).isDigit()) {
          valid = false;
          break;
        }
        state = 1;
        sensorId = ch.toString();
      } else if (state == 1) {
        if (!ch.codeUnitAt(0).isDigit()) {
          valid = false;
          break;
        }
        rssi = ch.toString();
        state = 2;
      } else {
        break;
      }
    }

    if (valid && state == 2) {
      final int? parsedRssi = int.tryParse(rssi);
      if (parsedRssi != null) {
        final String score;
        if (parsedRssi >= -50) {
          score = 'excellent';
        } else if (parsedRssi >= -67) {
          score = 'good';
        } else if (parsedRssi >= -80) {
          score = 'fair';
        } else if (parsedRssi >= -95) {
          score = 'weak';
        } else {
          score = 'dead';
        }
        result.add('${sensorId}S$score');
      }
    }
  }

  return result;
}

