              }
            }
          }
        }
        dp[r][c] = best + 1;
      }
    }
  }
  int maxF = 0;
  for (int f in dp[rows - 1]) {
    if (f > maxF) maxF = f;
  }
  if (maxF == 0) return "NONE";
