  Set<String> wordSet = wordDict.toSet();
  Map<String, int> dp = {};
  for (int i = 0; i < s.length; i++) {
    for (int j = 0; j < i; j++) {
      if (wordSet.contains(s.substring(j, i))) {
        if (dp.containsKey(s.substring(i))) {
          return true;
        }
        dp[s.substring(i)] = j;
      }
    }
  }
  return false;
}

List<List<String>> wordBreak2(String s, List<String> wordDict) {
  if (s.isEmpty) return [];
  List<bool> dp = List.filled(s.length + 1, false);
  dp[0] = true;
  Set<String> wordSet = wordDict.toSet();
  for (int i = 1; i <= s.length; i++) {
    for (int j = 0; j < i; j++) {
      if (wordSet.contains(s.substring(j, i))) {
        if (dp[j]) dp[i] = true;
      }
    }
  }
  List<List<String>> result = [];
  void backtrack(int start, List<String> current) {
    if (start == s.length) {
      result.add(List<String>.from(current));
      return;
    }
    for (int j = start; j < s.length; j++) {
      if (wordSet.contains(s.substring(j, s.length))) {
        current.add(s.substring(j, s.length));
        backtrack(j + 1, current);
        current.removeLast();
      }
    }
  }
  backtrack(0, []);
  return result;
}

int wordBreakMinLength(String s, List<String> wordDict) {
  if (s.isEmpty) return 0;
  int minLength = 1 << 30;
  for (String word in wordDict) {
    if (word.isNotEmpty && s.startsWith(word, 1)) {
      int len = word.length + wordBreakMinLength(s.substring(1), wordDict);
      if (len < minLength) minLength = len;
    }
  }
  return minLength;
}

