  Map<String, int> counts = {'ADD': 0, 'END': 0, 'UNDO': 0};
  List<String> result = [];
  List<String> stack = [];
  bool processing = false;
  int i = 0;

  while (i < log.length) {
    if (!processing) {
      if (log[i] == 'BEGIN') {
        processing = true;
        i++;
      } else {
        return result;
      }
    }

    if (processing) {
      String token = log[i];
      if (token == 'ADD') {
        counts['ADD'] = counts['ADD']! + 1;
        stack.add(token);
        i++;
      } else if (token == 'END') {
        if (stack.isEmpty) {
          return result;
        }
        String last = stack.removeLast();
        if (last == 'ADD') {
          counts['ADD'] = counts['ADD']! - 1;
        } else if (last == 'UNDO') {
          counts['UNDO'] = counts['UNDO']! - 1;
        }
        processing = false;
        i++;
      } else if (token == 'UNDO') {
        if (stack.isEmpty) {
          return result;
        }
        String last = stack.removeLast();
        if (last == 'ADD') {
          counts['ADD'] = counts['ADD']! - 1;
        } else if (last == 'UNDO') {
          counts['UNDO'] = counts['UNDO']! - 1;
        }
        processing = false;
        i++;
      } else {
        return result;
      }
    }
  }

  List<String> items = counts.keys.toList()..sort();
  for (String item in items) {
    result.add('$item: ${counts[item]}');
  }

  return result;
}

