void fn0() {

  List<int> search(String text, String pattern) {
    if (pattern.isEmpty) return [0];

    int n = text.length;
    int m = pattern.length;

    List<List<bool>> dp = List.generate(n + 1, (_) => List.filled(m + 1, false));

    for (int i = 0; i <= n; i++) {
      dp[i][0] = true;
    }
    for (int j = 0; j <= m; j++) {
      dp[0][j] = true;
    }

    for (int i = 1; i <= n; i++) {
      for (int j = 1; j <= m; j++) {
        if (text[i - 1] == pattern[j - 1]) {
          dp[i][j] = dp[i - 1][j - 1];
        } else {
          dp[i][j] = dp[i - 1][j];
        }
      }
    }

    List<int> result = [];
    if (dp[n][m]) result.add(0);
    for (int i = n; i >= 1; i--) {
      if (dp[i][m]) result.add(i);
    }
    return result;
  }

  String text = "HERE IS A SIMPLE EXAMPLE";
  String pattern = "EXAMPLE";

  List<int> positions = search(text, pattern);

  if (positions.isEmpty) {
    print("Pattern not found.");
  } else {
    print("Pattern found at positions: ${positions.join(", ")}");
  }
}

