int fn0(List<int> sortedStocks, int target, int maxGap) {
  if (sortedStocks.isEmpty) return -1;
  int left = 0, right = sortedStocks.length - 1, result = -1;
  while (left <= right) {
    int mid = left + (right - left) ~/ 2;
    if (sortedStocks[mid] <= target) {
      result = mid;
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }
  if (result == -1) return -1;
  int low = result - maxGap, high = result + maxGap;
  while (low < high) {
    int mid = low + (high - low) ~/ 2;
    if (sortedStocks[mid] <= target) {
      low = mid + 1;
    } else {
      high = mid;
    }
  }
  return low;
}

