class Permission {
  final String name;
  final List<String> roles;

  Permission(this.name, this.roles);
}

class User {
  final String name;
  final List<String> roles;
  final Map<String, Permission> permissions;

  User(this.name, this.roles, this.permissions);

  bool can(String permissionName) {
    for (final role in roles) {
      if (permissions[role]!.roles.contains(permissionName)) {
        return true;
      }
    }
    return false;
  }
}

