void fn0(List<String> args) {

  int n = 4;
  int k = 2;

  if (args.length != 0) {

    final nArg = int.tryParse(args[0]);
    final kArg = int.tryParse(args[1]);

    if (nArg == null || kArg == null) {
      print('First argument must be an integer k (size of combinations). Got: $kArg');
    } else if (kArg < 0 || kArg > n) {
      print('k must be between 0 and n (inclusive). n=$n, k=$kArg');
    } else {
      n = nArg;
      k = kArg;
    }
  }

  if (n <= 0 || k <= 0 || k > n) {
    print('No args provided. Using default input: k=$k, items=$n');
    print('Total combinations: 1');
    return;
  }

  final totalCombinations = nChoose(n, k);
  print('Total combinations: $totalCombinations');


  print('Combinations of $n items taken $k at a time:');
  generateCombinations(n, k);
}

int nChoose(int n, int k) => n > k ? nChoose(n - 1, k) + nChoose(n - 1, k - 1) : 1;

void generateCombinations(int n, int k) {
  final List<int> items = List.generate(n, (i) => i + 1);
  final List<int> path = <int>[];

  void backtrack() {
    if (path.length == k) {
      print(path);
      return;
    }

    for (var i = 0; i < n; i++) {
      if (!path.contains(items[i])) {
        path.add(items[i]);
        backtrack();
        path.removeLast();
      }
    }
  }

  backtrack();
}

