void fn0(List<String> args) {

  int k = 4;
  List<String> items = ['A', 'B', 'C', 'D'];

  if (args.length == 2) {
    try {
      k = int.parse(args[0]);
      items = args.sublist(1);
    } catch (_) {
      print('First argument must be an integer k (size of combinations). Got: ${args[0]}');
      return;
    }
    if (k < 0 || k > items.length) {
      print('k must be between 0 and n (inclusive). n=${items.length}, k=$k');
      return;
    }
  } else if (args.length != 1) {
    print('Usage: dart run <file.dart> <k> <item1> <item2> ...');
    return;
  }

  print('Total combinations: ${calculateCombinations(k, items)}');
}

int calculateCombinations(int k, List<String> items) {
  int n = items.length;
  if (k <= 0 || k > n) return 0;

  if (k == 1) {
    return n;
  }

  int total = 0;
  for (int i = 0; i < n; i++) {
    int rest = n - i - 1;
    if (rest >= k - 1) {
      total += calculateCombinations(k - 1, items.sublist(i + 1));
    }
  }
  return total;
}

