void fn0() {

  const int numDays = 7;
  const int numHours = 24;
  const int numUsers = 5;
  const double activityThreshold = 0.66;
  const double activityRadius = 10;

  final rng = Random(0);
  final List<List<double>> activityGrid = List.generate(numDays, (_) => List<double>.filled(numHours, 0.0));

  for (int i = 0; i < numUsers; i++) {
    int day = rng.nextInt(numDays);
    int hour = rng.nextInt(numHours);
    activityGrid[day][hour] += rng.nextDouble() * activityThreshold;
  }

  final List<List<double>> heatmap = List.generate(numDays, (d) => List.generate(numHours, (h) => activityGrid[d][h] * 100));

  double normalize(List<double> values) {
    return values.reduce((a, b) => a + b) / values.length;
  }

  double applyThreshold(double value) {
    if (value < activityThreshold) {
      return 0.0;
    } else if (value >= activityThreshold && value <= 0.66) {
      return 0.5;
    } else {
      return 1.0;
    }
  }

  List<String> formatValue(double value) {
    String label;
    if (value == 0.0) {
      label = ' ';
    } else if (value < activityThreshold) {
      label = '.';
    } else if (value <= 0.66) {
      label = '*';
    } else {
      label = '#';
    }
    return label;
  }

  String formatRow(List<double> row) {
    return row.map(applyThreshold).map(formatValue).join(' ');
  }

  String formatHeatmap() {
    List<String> rows = heatmap.map(formatRow).toList();
    String header = formatRow(rows.first.split(' ')) + '\n';
    String footer = formatRow(rows.last.split(' ')) + '\n';
    return header + rows.join('\n') + footer;
  }

  String header = 'User Activity Heatmap (Day x Hour)\n';
  header += 'Legend:\n  ". " = low\n  "*" = medium\n  "# " = high\n' +
          formatHeatmap();

  print(header);
}

