      index += 1;
      continue;
    }
    if (card.length != 2) {
      result['Invalid card'] = (result['Invalid card'] ?? 0) + 1;
      return result;
    }
    String rank = card[0];
    String suit = card[1];
    if (!rankOrder.containsKey(rank) || !suitOrder.containsKey(suit)) {
      result['Invalid card'] = (result['Invalid card'] ?? 0) + 1;
      return result;
    }
    if (rank == 'X') {
      String wildSuit = wildCards[suit]!;
      result[wildSuit] = (result[wildSuit] ?? 0) + 1;
      continue;
    }
    if (seenCards.contains(card)) {
      result['Repeated card'] = (result['Repeated card'] ?? 0) + 1;
      return result;
    }
    seenCards.add(card);
    int rankValue = rankOrder[rank]!;
    int suitOrderValue = suitOrder[suit]!;
