void fn0(List<String> args) {

  final n = args.isNotEmpty ? int.parse(args[0]) : 8;

  final totalSolutions = <List<String>>[];

  void solve(int remaining, List<String> queens, List<String> board) {

    if (remaining == 0) {

      final solution = <String>[];
      for (final pos in queens) {
        solution.add('Q $pos');
      }
      totalSolutions.add(solution);
      return;
    }

    for (var file = 0; file < board.length; file++) {

      if (board[file].contains('Q')) {
        continue;
      }

      final safe = List<bool>.filled(board.length, false);
      for (var i = 0; i < queens.length; i++) {
        final queenPos = queens[i];
        if (queenPos.isEmpty) {
          continue;
        }
        final queenFile = queenPos.codeUnitAt(0) - 97;
        final queenRank = int.parse(queenPos.substring(1));
        if (queenRank == file ||
            (queenRank - file).abs() == (queenFile - queenRank).abs()) {
          safe[queenRank] = true;
        }
      }

      for (var rank = 0; rank < board.length; rank++) {
        if (safe[rank]) {
          queens.add('$file$rank');
          board[file] = board[file] + 'Q';
          solve(remaining - 1, queens, board);
          queens.removeLast();
          board[file] = board[file].substring(0, file.length);
        }
      }
    }
  }

  print('Solving N-Queens for N=$n');
  solve(n, <String>[], <String>[for (var i = 0; i < n; i++) List<String>.filled(n, '.').join(' ')]);

  print('Total solutions: ${totalSolutions.length}');
  for (var i = 0; i < totalSolutions.length; i++) {
