class Quaternion {
  final double x, y, z, w;

  Quaternion(this.x, this.y, this.z, this.w);

  static Quaternion fromList(List<double> list) {
    if (list.length != 4) throw ArgumentError('Invalid quaternion length');
    return Quaternion(list[0], list[1], list[2], list[3]);
  }

  Quaternion operator +(Quaternion q) => Quaternion(x + q.x, y + q.y, z + q.z, w + q.w);

  Quaternion operator -(Quaternion q) => Quaternion(x - q.x, y - q.y, z - q.z, w - q.w);

  Quaternion operator *(double c) => Quaternion(x * c, y * c, z * c, w * c);

  Quaternion operator *(Quaternion q) => Quaternion(
        x * q.w - y * q.z - z * q.y,
        x * q.z + y * q.w - z * q.x,
        x * y - y * q.x,
        x * z + y * q.y,
      );

  Quaternion operator /(double c) {
    if (c == 0.0) throw ArgumentError('Cannot divide by zero');
    return Quaternion(x / c, y / c, z / c, w / c);
  }

  Quaternion conjugate() => Quaternion(x, y, z, -w);

  double norm() {
    final double a = x * x + y * y + z * z + w * w;
    if (a < 1e-6) return 0.0;
    return sqrt(a);
  }

  Quaternion normalized() => this / norm();

  Quaternion inverse() {
    final double norm2 = norm() * norm();
    if (norm2 < 1e-6) return Quaternion(0.0, 0.0, 0.0, 0.0);
    return Quaternion(x / norm2, y / norm2, z / norm2, w / norm2);
  }

  @override
  String toString() {
    return 'Quaternion($x, $y, $z, $w)';
  }
}

