class Quaternion {
  final double x, y, z, w;

  Quaternion(this.x, this.y, this.z, this.w);

  double get norm => x * x + y * y + z * z + w * w;

  Quaternion operator +(Quaternion other) => Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);

  Quaternion operator -(Quaternion other) => Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);

  Quaternion operator *(double scalar) => Quaternion(x * scalar, y * scalar, z * scalar, w * scalar);

  Quaternion operator *(Quaternion other) {
    return Quaternion(
      x * other.w - y * other.z - z * other.y + w * other.x,
      x * other.z + y * other.w + z * other.x - w * other.y,
      x * other.y - y * other.x + z * w - w * other.z,
      x * other.w + y * other.y + z * other.z - w * other.x,
    );
  }

  Quaternion operator /(Quaternion other) {
    return Quaternion(
      (x * other.w + y * other.z + z * other.y - w * other.x) / (other.norm * other.norm),
      (x * other.z - y * other.w + z * other.x + w * other.y) / (other.norm * other.norm),
      (x * y + y * other.x - z * w + w * other.z) / (other.norm * other.norm),
      (x * w + y * other.y - z * other.z) / (other.norm * other.norm),
    );
  }

  Quaternion conjugate() => Quaternion(x, y, z, -w);

  Quaternion inverse() {
    var n = norm;
    if (n == 0) {
      throw ArgumentError('Cannot invert zero quaternion');
    }
    return (1 / n) * conjugate();
  }

  Quaternion normalize() {
    var n = norm;
    if (n == 0) {
      throw ArgumentError('Cannot normalize zero quaternion');
    }
    return (1 / n) * Quaternion(x / n, y / n, z / n, w / n);
  }

  Quaternion rotate90(Vector3 axis) {
    var q = Quaternion(0.0, 0.0, 0.0, 1.0);
    for (var i = 0; i < 4; i++) {
      var c = 0.5 * axis.x;
      var s = 0.5 * axis.y;
      var u = 0.5 * axis.z;
      var v = 1.0 - 3.0 * c * c - 3.0 * s * s;
      if (i % 2 == 0) {
        q = q * (2.0 * u - v);
      } else {
        q = q * (v + 2.0 * u);
      }
    }
    return q;
  }

  @override
  String toString() {
    return 'Quaternion($x, $y, $z, $w)';
  }
}

