/// Abstract base class representing quaternions.
abstract class Quaternion {

  factory Quaternion(double x, double y, double z, double w) {
    return _Quaternion(x, y, z, w);
  }


  double x();
  double y();
  double z();
  double w();

  Quaternion conjugate();

  Quaternion normalized();

  Quaternion inverse();

  Quaternion squaredNorm();

  double norm();


  factory Quaternion.fromList(List<double> parts) {
    if (parts.length != 4) {
      throw ArgumentError('Invalid quaternion length');
    }
    return _Quaternion(parts[0], parts[1], parts[2], parts[3]);
  }


  factory Quaternion.fromEuler(double phi, double theta, double psi) {
    double sinPhi = sin(phi);
    double cosPhi = cos(phi);
    double sinTheta = sin(theta);
    double cosTheta = cos(theta);
    double sinPsi = sin(psi);
    double cosPsi = cos(psi);

    return _Quaternion(
      0.0, 0.0, 0.0,
      sinPhi * cosTheta * cosPsi - cosPhi * sinTheta * sinPsi,
      sinPhi * cosTheta * sinPsi + cosPhi * sinTheta * cosPsi,
      cosPhi * sinTheta * cosPsi + sinPhi * sinTheta * sinPsi,
      cosPhi * cosTheta * sinPsi - sinPhi * sinTheta * cosPsi,
    );
  }
}

/// Class implementing the Quaternion interface.
class _Quaternion implements Quaternion {
  final double x;
  final double y;
  final double z;
  final double w;

  _Quaternion(this.x, this.y, this.z, this.w);

  @override
  double x() => x;
  @override
  double y() => y;
  @override
  double z() => z;
  @override
  double w() => w;

  @override
  Quaternion conjugate() {
    return _Quaternion(x, y, z, -w);
  }

  @override
  Quaternion normalized() {
    final double norm = squaredNorm();
    if (norm == 0.0) {
      throw ArgumentError('Cannot normalize zero quaternion');
    }
    return _Quaternion(x / norm, y / norm, z / norm, w / norm);
  }

  @override
  Quaternion inverse() {
    final double norm = squaredNorm();
    if (norm == 0.0) {
      throw ArgumentError('Cannot invert zero quaternion');
    }
    return _Quaternion(
      x / norm,
      y / norm,
      z / norm,
      -w / norm,
    );
  }

  @override
  Quaternion squaredNorm() {
    return _Quaternion(
      x * x + y * y + z * z + w * w,
      0.0,
      0.0,
      0.0,
    );
  }

  @override
  double norm() => sqrt(squaredNorm());

  @override
  String toString() {
    return 'Quaternion($x, $y, $z, $w)';
  }
}

