/// Quaternion class representing a four-dimensional unit vector in
/// space. A quaternion represents a rotation combined with a scaling
/// factor.
class Quaternion {
  final double x;
  final double y;
  final double z;
  final double w;

  Quaternion(this.x, this.y, this.z, this.w);

  static const Quaternion zero = Quaternion(0.0, 0.0, 0.0, 1.0);

  /// Returns the conjugate quaternion.
  Quaternion conjugate() {
    return Quaternion(x, y, z, -w);
  }

  /// Returns the inverse quaternion.
  Quaternion inverse() {
    final d = w * w;
    if (d == 0.0) {
      throw ArgumentError('Cannot invert zero quaternion');
    }
    final inv = 1.0 / d;
    return Quaternion(x * inv, y * inv, z * inv, -w * inv);
  }

  /// Returns the norm of the quaternion, which is the square root of
  /// the sum of the squares of the four components.
  double norm() {
    return sqrt(x * x + y * y + z * z + w * w);
  }

  /// Returns the normalized quaternion, which is the self of this
  /// quaternion divided by its norm.
  Quaternion normalized() {
    if (norm() == 0.0) {
      throw ArgumentError('Cannot normalize zero quaternion');
    }
    return Quaternion(x / norm(), y / norm(), z / norm(), w / norm());
  }

  /// Returns the sum of two quaternions.
  Quaternion operator +(Quaternion other) {
    return Quaternion(
      x + other.x,
      y + other.y,
      z + other.z,
      w + other.w,
    );
  }

  /// Returns the difference of two quaternions.
  Quaternion operator -(Quaternion other) {
    return Quaternion(
      x - other.x,
      y - other.y,
      z - other.z,
      w - other.w,
    );
  }

  /// Returns the product of two quaternions.
  Quaternion operator *(Quaternion other) {
    return Quaternion(
      x * other.x - y * other.y - z * other.z - w * other.w,
      x * other.y + y * other.x + z * other.w - w * other.z,
      x * other.z - y * other.w + z * other.x + w * other.y,
      x * other.w + y * other.z - z * other.y + w * other.x,
    );
  }

  /// Returns the product of a quaternion with a double.
  Quaternion operator *(double d) {
    return Quaternion(x * d, y * d, z * d, w * d);
  }

  /// Returns the product of two doubles.
  static double operator *(double a, double b) {
    return a * b;
  }

  @override
  String toString() {
    return 'Quaternion($x, $y, $z, $w)';
  }
}

