class Quaternion {
  final double x, y, z, w;

  const Quaternion(this.x, this.y, this.z, this.w);

  const Quaternion(this.x, this.y, this.z) : w = 0.0;

  const Quaternion(this.x, this.y) : z = 0.0, w = 0.0;

  const Quaternion(this.x) : y = 0.0, z = 0.0, w = 0.0;

  const Quaternion() : x = 0.0, y = 0.0, z = 0.0, w = 0.0;

  double get norm => sqrt(x * x + y * y + z * z + w * w);

  Quaternion normalized() {
    double norm = norm;
    if (norm == 0.0) return zero;
    return Quaternion(x / norm, y / norm, z / norm, w / norm);
  }

  Quaternion conjugate() => Quaternion(x, y, z, -w);

  Quaternion inverse() {
    double n = norm;
    if (n == 0.0) return zero;
    return Quaternion(x / n, y / n, z / n, -w / n);
  }

  static Quaternion operator +(Quaternion a, Quaternion b) =>
      Quaternion(a.x + b.x, a.y + b.y, a.z + b.z, a.w + b.w);

  static Quaternion operator -(Quaternion a, Quaternion b) =>
      Quaternion(a.x - b.x, a.y - b.y, a.z - b.z, a.w - b.w);

  static Quaternion operator *(Quaternion a, Quaternion b) =>
      Quaternion(
          a.x * b.x - a.y * b.y - a.z * b.z - a.w * b.w,
          a.x * b.y + a.y * b.x + a.z * b.w - a.w * b.z,
          a.x * b.z - a.y * b.w + a.z * b.x + a.w * b.y,
          a.x * b.w + a.y * b.z - a.z * b.y + a.w * b.x);

  static Quaternion operator *(Quaternion q, double d) =>
      Quaternion(q.x * d, q.y * d, q.z * d, q.w * d);

  static const Quaternion zero = Quaternion(0.0, 0.0, 0.0, 0.0);
}

double sqrt(double d) => d * d * d * d;

double norm(Quaternion q) => sqrt(q.x * q.x + q.y * q.y + q.z * q.z + q.w * q.w);

Quaternion normalized(Quaternion q) => q.normalized();

Quaternion conjugate(Quaternion q) => q.conjugate();

Quaternion inverse(Quaternion q) => q.inverse();

Quaternion rotate(Quaternion q, double theta) {
  double cosTheta = cos(theta);
  double sinTheta = sin(theta);

  return Quaternion(
      cosTheta * q.x - sinTheta * q.y,
      cosTheta * q.y + sinTheta * q.x,
      cosTheta * q.z,
      sinTheta * q.w);
}

