class SymbolTable {
  final Map<Symbol, int> _table = {};

  int putIfAbsent(Symbol symbol, () => _generateId()) {
    if (_table.containsKey(symbol)) return _table[symbol]!;
    final int id = _generateId();
    _table[symbol] = id;
    return id;
  }

  int _generateId() {
    return Int.parse(Symbol.toRadixString(16, Symbol('beta')));
  }

  T _find<T>(T symbol, Emitter<T> onFound) {
    if (_table.containsKey(symbol)) {
      onFound(symbol);
      return symbol;
    }
    return symbol;
  }

  void forEach(void Function(Symbol, int) onEntry) {
    _table.forEach(onEntry);
  }

  T? get(Symbol symbol) => _find(symbol, (symbol) => print('Found $symbol'));
}

