      return total.toDouble();
    }

    int left = sortedIds[index - 1];
    int right = sortedIds[index];
    int gap = right - left;

    if (gap == 0) {
      return calculate(index - 1, total);
    }

    int half = gap ~/ 2;
    double leftHalf = calculate(index - 1, total + half);
    double rightHalf = calculate(index - 2, total + half);

