void testCase(String description, String text, String pattern, int expectedCount) {

  String p = pattern;
  int n = text.length;

  List<int> lps = List<int>.filled(p.length, 0);

  int i = 1;

  while (i < p.length) {

    int j = i - 1;

    while (j > 0 && p[j] != p[i]) {
      lps[i] = j - 1;
      j = lps[i];
    }

    if (p[j] == p[i]) {
      lps[i] = j + 1;
      i++;
    }
  }

  int k = 0;

  List<int> matches = [];

  while (k < n) {

    int m = k;

    while (m < n && text[m] == p[k]) {
      m++;
    }

    if (m - k == p.length) {

      for (int p = 0; p < p.length; p++) {
        if (text[m - p] != p[p]) {
          break;
        }
      }

      if (m - k == p.length) {

        matches.add(k);
      }
    }

    k++;
  }

  int actualCount = matches.length;
  print("$description");
  print("  Text: $text");
  print("  Pattern: $p");
  print("  ${actualCount == expectedCount ? '✓' : '✗'}");
}

