    print('F(n) calculates the number of ways to partition [n] into a sum of one or more distinct positive integers.');
    return;
  }

  final n = int.tryParse(args[0]);
  if (n == null || n < 0) {
    print('Please provide a non-negative integer (e.g., "dart run main.dart 20").');
    return;
  }

  const int mod = 1000000007;

  final dp = List.filled(n + 1, 0);
  dp[0] = 1;

  for (int i = 1; i <= n; i++) {
    for (int j = i - 1; j >= 1; j--) {
      if (j == 0) {
        dp[i] = (dp[i] + dp[i - 1]) % mod;
      } else {
        dp[i] = (dp[i] + dp[j] * dp[i - j - 1]) % mod;
      }
    }
  }

  print('F($n) = ${dp[n]}');
}

