  while (lo <= hi) {
    int mid = (lo + hi) >> 1;
    if (targetSizes[mid] <= s) {
      counts[mid]++;
      lo = mid + 1;
    } else {
      hi = mid - 1;
    }
  }
  int first = -1;
  for (int i = 0; i < n; i++) {
    if (counts[i] == k) {
      first = i;
      break;
    }
  }
  if (first == -1) return -1;
  int last = first + (k - 1);
  if (last >= n) return -1;
  int sum = 0;
  for (int i = first; i <= last; i++) {
    sum += targetSizes[i];
  }
  int prefix = 0;
  for (int i = 0; i < first; i++) {
    prefix += targetSizes[i];
  }
  int suffix = 0;
  for (int i = last + 1; i < n; i++) {
    suffix += targetSizes[i];
  }
  if (sum == prefix + suffix) return last;
  return -1;
}

@pragma('vm:never-inline')
@pragma('vm:entry-point')

int fn0(List<int> amounts, int threshold) {
  int n = amounts.length;
  if (n == 0) return 0;
  List<bool> dp = List.filled(n + 1, false);
  dp[0] = true;
  for (int i = 1; i <= n; i++) {
    for (int j = 0; j < i; j++) {
      if (dp[j]) {
        int sum = 0;
        for (int k = j; k < i; k++) {
          sum += amounts[k];
          if (sum > threshold) break;
          if (dp[i - k - 1]) {
            dp[i] = true;
            break;
          }
        }
      }
    }
  }
  return dp[n] ? 1 : 0;
}

