import 'dart:async';
import 'dart:convert';
class User {
  final String name;
  final List<String> roles;

  User({required this.name, required this.roles});
}

class Role {
  final String name;
  final List<String> permissions;

  Role({required this.name, required this.permissions});
}

class Resource {
  final String name;

  Resource(this.name);
}

class AccessControlSystem {
  final Map<String, List<String>> users;
  final Map<String, List<String>> roles;
  final Map<String, List<String>> resources;
  final Map<String, List<String>> permissions;
  final Map<String, int> userPermissions;
  final Map<String, int> rolePermissions;
  final Map<String, int> resourcePermissions;

  AccessControlSystem(this.users, this.roles, this.resources, this.permissions) {
    userPermissions = {};
    rolePermissions = {};
    resourcePermissions = {};

    users.forEach((user, roles) {
      for (final role in roles) {
        userPermissions[role] = 0;
        rolePermissions[role] = 0;
      }
    });

    resources.forEach((resource, permissions) {
      for (final permission in permissions) {
        resourcePermissions[permission] = 0;
      }
    });

    for (final role in roles.keys) {
      for (final permission in permissions.keys) {
        if (permissions[permission] == true) {
          rolePermissions[role] = (rolePermissions[role] ?? 0) + 1;
        }
      }
    }

    for (final user in users.keys) {
      for (final resource in resources.keys) {
        if (permissions.containsKey(resource)) {
          userPermissions[user] = (userPermissions[user] ?? 0) + 1;
        }
      }
    }
  }

  bool hasAccess(String user, String resource, String action) {
    if (!users.containsKey(user)) {
      return false;
    }
    if (!resources.containsKey(resource)) {
      return false;
    }

    if (action == 'read' || action == 'view') {
      return (userPermissions[user] ?? 0) >= 1 &&
          resourcePermissions[resource]!.contains(action);
    }
    if (action == 'write' || action == 'edit') {
      return (userPermissions[user] ?? 0) >= 2 &&
          resourcePermissions[resource]!.contains(action);
    }
    if (action == 'delete' || action == 'remove') {
      return (userPermissions[user] ?? 0) >= 3 &&
          resourcePermissions[resource]!.contains(action);
    }

    return false;
  }

  void logAccess(String user, String resource, String action, bool granted) {
    final status = granted ? 'SUCCESS' : 'DENIED';
    final timestamp = DateTime.now().toString();
    print('[$timestamp] User "$user" $action "$resource": $status');
    print('  ↳ ${granted ? "✓" : "✗"} Access granted/denied\n');
  }
}

