void testAccess(String user, String resource, [bool expectedResult = true]) {

  String action = expectedResult ? 'SUCCESS' : 'DENIED';
  String result = (user, resource, action) {
    return expectedResult
        ? '  ➜ Access GRANTED (Role: ${rolePermissions[user]})'
        : '  ➜ Access DENIED (Insufficient permissions)';
  };

  print('Attempting to $action ${user} to access $resource:');
  print('  ➜ ${result}');
}

void auditLog(String user, String resource, String action) {
  StringBuffer sb = StringBuffer();
  sb.write('Timestamp: ${DateTime.now().toString()}');
  sb.write(' | User: $user');
  sb.write(' | Resource: $resource');
  sb.write(' | Action: $action');
  print(sb.toString());
}

