  roleHierarchy[target] = roleHierarchy[source]!.map((perm) => perm).toList();
  print('New role for $source: $target');
  print('Role Hierarchy: ${roleHierarchy.keys}');
}

Map<String, List<String>> rolePermissions = {};

void grantRole(String role, String resource, String action) {
  if (!rolePermissions.containsKey(role)) {
    rolePermissions[role] = [];
  }
  rolePermissions[role]!.add(resource);
}

void denyRole(String role, String resource, String action) {
  if (rolePermissions.containsKey(role)) {
    rolePermissions[role]!.remove(resource);
  }
}

