      found = true;
      break;
    }
  }
  if (!found) {
    print('  ➜ User "$role" not found\n');
    return false;
  }

  return requiredPermissions.contains(currentRole);
}

void grantRole(String role, String user) {
  if (!userRoles.contains(role)) {
    print('  ➜ New role "$role" not found');
    return;
  }

  for (var entry in userPermissions[user] ?? const []) {
    if (entry == role) {
      print('  ➜ Access already granted for "$role"');
      return;
    }
  }

  userPermissions[user]!.add(role);
  print('  ➜ Access granted for "$role"');
}

