@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  final items = <String>['Milk', 'Bread', 'Butter'];

  final minSupport = 0.5;

  final transactions = <List<String>>[
    ['Milk', 'Bread'],
    ['Milk', 'Butter'],
    ['Bread', 'Butter'],
  ];

  final numTransactions = transactions.length;
  final numItems = items.length;

  final Set<List<String>> allSubsets = {};
  final List<String> temp = List<String>.from(items);
  generateSubsets(temp, allSubsets, 0);

  final Set<String> frequentItemsets = {};
  final Map<List<String>, int> supportCounts = {};

  for (final subset in allSubsets) {
    final subItems = subset.toList();
    final support = subItems.length / numTransactions;
    if (support >= minSupport) {
      for (final item in subItems) {
        supportCounts[item] = (supportCounts[item] ?? 0) + 1;
      }
      frequentItemsets.add(subItems.join(','));
    }
  }

  print('Frequent Itemsets:');
  print(frequentItemsets);

  print('\nAssociation Rules:');
  final Map<String, Map<String, int>> itemFrequency = {};
  for (final item in items) {
    itemFrequency[item] = {};
  }
  for (final transaction in transactions) {
    for (final item in transaction) {
      itemFrequency[item] = (itemFrequency[item] ?? <String, int>{})..add(item);
    }
  }
  for (final entry in itemFrequency.entries) {
    if (entry.value.length > 1) {
      final Map<String, int> frequentItems = {};
      entry.value.forEach((k, v) => frequentItems[k] = v);
      final String antecedent = frequentItems.keys.toList().join(' ');
      final List<String> consequents = frequentItems.values.where((v) => v > 1).keys.toList();
      for (final c in consequents) {
        final confidence = (frequentItems[c] ?? 0) / frequentItems[antecedent];
        print('Rule: $antecedent => $c (support: ${frequentItems[c]} / ${frequentItems[antecedent]}, confidence: $confidence)');
      }
    }
  }
}

void generateSubsets(
    List<String> items, Set<List<String>> allSubsets, int index) {
  if (index == items.length) {
    allSubsets.add(List<String>.from(items));
    return;
  }
  generateSubsets(items, allSubsets, index + 1);
  generateSubsets(items, allSubsets, index + 1);
  items.removeAt(index);
  generateSubsets(items, allSubsets, index + 1);
  items.insertAt(index, items.removeAt(index));
}

