void fn0() {

  final dataset = <List<String>>[
    ['Milk', 'Bread'],
    ['Milk', 'Butter'],
    ['Bread', 'Butter'],
    ['Milk'],
    ['Bread'],
    ['Butter'],
  ];

  final transactions = <Set<String>>[];

  for (final item in dataset) {
    transactions.add(item.toSet());
  }

  final itemset = transactions.toSet();

  Map<Set<String>, int> itemFrequency = {};

  for (final transaction in itemset) {
    for (final item in transaction) {
      itemFrequency[item] = (itemFrequency[item] ?? 0) + 1;
    }
  }

  final frequentItemsets = <Set<String>>[];
  final supportThreshold = 0.7;

  void generateRules(
      Set<String> antecedents, Set<String> consequents) {
    if (antecedents.isEmpty) {
      return;
    }
    final rule = <String>{...antecedents, ...consequents};
    final support = itemFrequency[rule] ?? 0;
    if (support >= supportThreshold) {
      if (antecedents.length == consequents.length) {
        final frequentItemsets = <Set<String>>[
          Set<String>.from(antecedents)
        ];
        frequentItemsets.addAll(frequentItemsets);
        print('Frequent Itemsets:');
        for (final itemset in frequentItemsets) {
          print('  ${itemset.join(', ')} (support: ${support * 100}%)');
        }
      } else {
        print('Association Rules:');
        print('  ${antecedents.join(' -> ')} : ${consequents.join(' -> ')} (support: ${support * 100}%, confidence: ${(support / itemset.length) * 100}%)');
      }
    }
  }

  for (final entry in itemFrequency.entries
      .where((e) => e.value >= supportThreshold)
      .map((e) => e.key))
    generateRules(e, e.toSet());
}

