    'Bread': 1,
    'Butter': 0,
    'Milk': 1,
    'Bread': 0,
    'Butter': 1,
    'Milk': 1,
    'Bread': 1,
    'Butter': 1,
    'Milk': 0,
    'Bread': 1,
    'Butter': 1,
  };

  int minSupport = 2; 
  int minConfidence = 0.5; 

  List<String> items = transactions.keys.toList();

  Map<List<String>, int> supportCount = {};
  Set<List<String>> frequentItemsets = {};

  for (var transaction in transactions.entries) {

    int support = 0;
    Set<String> frequent = {};

    for (int i = 0; i < items.length; i++) {
      if (transaction.value == 1) {
        if (i < items.length) {
          frequent.add(items[i]);
        }
      }
    }

    support = (frequent.length / items.length) * 100;

    if (support >= minSupport) {

      supportCount[frequent] = (supportCount[frequent] ?? 0) + 1;

