class Rectangle {
  final double centerX;
  final double centerY;
  final double halfWidth;
  final double halfHeight;

  Rectangle(
      {required this.centerX,
      required this.centerY,
      required this.halfWidth,
      required this.halfHeight});

  Rectangle.square(double centerX, double centerY, double side)
      : centerX = centerX,
        centerY = centerY,
        halfWidth = side / 2,
        halfHeight = side / 2;

  Rectangle.random(
      double maxX, double maxY, Random random, int k) {
    final points = <Point>[];
    while (points.length < k) {
      final point = Point.random(maxX, maxY, random);
      if (points.isEmpty || points.last != point) points.add(point);
    }
    final centerX = points.map((p) => p.x).reduce((a, b) => a + b) / k;
    final centerY = points.map((p) => p.y).reduce((a, b) => a + b) / k;
    return Rectangle(centerX: centerX, centerY: centerY, halfWidth: points[0].x, halfHeight: points[0].y);
  }

  Rectangle.circle(double centerX, double centerY, double radius)
      : centerX = centerX,
        centerY = centerY,
        halfWidth = radius,
        halfHeight = radius;

  Rectangle.fromList(List<double> list)
      : centerX = list[0],
        centerY = list[1],
        halfWidth = list[2],
        halfHeight = list[3];

  Rectangle.fromRectangle(Rectangle other)
      : centerX = other.centerX,
        centerY = other.centerY,
        halfWidth = other.halfWidth,
        halfHeight = other.halfHeight;

  Rectangle.expand(Rectangle a, Rectangle b)
      : centerX = a.centerX < b.centerX
              ? a.centerX
              : b.centerX,
        centerY = a.centerY < b.centerY
            ? a.centerY
            : b.centerY,
        halfWidth = a.halfWidth > b.halfWidth
            ? a.halfWidth
            : b.halfWidth,
        halfHeight = a.halfHeight > b.halfHeight
            ? a.halfHeight
            : b.halfHeight;

  Rectangle get bounded => Rectangle.fromRectangle(this);

  bool contains(Point p) =>
      (p.x - centerX).abs() <= halfWidth &&
      (p.y - centerY).abs() <= halfHeight;

  bool intersects(Rectangle other) =>
      !(other.centerX < centerX - halfWidth ||
          other.centerX > centerX + halfWidth ||
          other.centerY < centerY - halfHeight ||
          other.centerY > centerY + halfHeight);

  @override
  String toString() => 'Rectangle(center: ($centerX, $centerY), halfWidth: $halfWidth, halfHeight: $halfHeight)';
}

