      !(
        other.x > x + width ||
        other.x < x ||
        other.y > y + height ||
        other.y < y
      );

  Rectangle union(Rectangle other) =>
      Rectangle.fromPoints(this, other);

  Rectangle intersection(Rectangle other) =>
      Rectangle.fromPoints(
        Point.min(this, other),
        Point.max(this, other),
      );

  Rectangle difference(Rectangle other) =>
      Rectangle.fromPoints(
        this.union(other),
        other,
      );

  Rectangle dilate(double factor) =>
      Rectangle.square(x, y, width * factor, height * factor);

  Rectangle erode(Rectangle other) =>
      difference(other.dilate(0.0001));

  Rectangle translate(double dx, double dy) =>
      Rectangle.square(x + dx, y + dy, width, height);
}

