    required this.halfWidth,
    required this.halfHeight,
  });

  Rectangle.square(double side)
      : this(x: side / 2, y: side / 2, halfWidth: side / 4, halfHeight: side / 4);

  Rectangle.fromPoints(Point p1, Point p2)
      : x = p1.x < p2.x ? p1.x : p2.x,
        y = p1.y < p2.y ? p1.y : p2.y,
        halfWidth = (p1.x - x).abs() / 2,
        halfHeight = (p1.y - y).abs() / 2;

  Rectangle.random(Random rng, double halfWidth, double halfHeight)
      : x = rng.nextDouble() * halfWidth * 2 - halfWidth,
        y = rng.nextDouble() * halfHeight * 2 - halfHeight,
        halfWidth = halfWidth / 2,
