      other.contains(Point(x - halfWidth, y - halfHeight)) &&
      other.contains(Point(x + halfWidth, y - halfHeight)) &&
      other.contains(Point(x - halfWidth, y + halfHeight)) &&
      other.contains(Point(x + halfWidth, y + halfHeight));

  Rectangle union(Rectangle other) =>
      Rectangle.fromPoints(Point(x - halfWidth, y - halfHeight),
          Point(x + halfWidth, y + halfHeight));

  Rectangle intersection(Rectangle other) =>
      Rectangle.fromPoints(
          other.contains(Point(x - halfWidth, y - halfHeight))
              ? Point(x - halfWidth, y - halfHeight)
              : Point.random(
                  other.rng, other.halfWidth, other.halfHeight),
          other.contains(Point(x + halfWidth, y - halfHeight))
              ? Point(x + halfWidth, y - halfHeight)
              : Point.random(
                  other.rng, other.halfWidth, other.halfHeight));

  Rectangle difference(Rectangle other) =>
      union(other.intersection(Rectangle.square(halfWidth + other.halfWidth)));
}

