    [9.0, 6.0],
    [8.0, 2.0],
    [7.0, 4.0],
    [2.0, 5.0],
    [3.0, 7.0],
  ];

  int numClusters = 3;
  double eps = 1.5; 
  int minPts = 2; 

  List<List<int>> clusters = List.generate(numClusters, (i) => <int>[]);

  for (int i = 0; i < points.length; i++) {
    List<int> neighbors = <int>[];
    for (int j = 0; j < points.length; j++) {
      if (i == j) continue;
      if (distance(points[i], points[j]) <= eps) {
        neighbors.add(j);
      }
    }

    if (neighbors.length < minPts) {
      clusters[0].add(i);
    } else {
      Set<int> uniqueLabels = {};
      for (int neighbor in neighbors) {
        uniqueLabels.add(clusters[neighbor]);
      }
      if (uniqueLabels.length > 1) {
        clusters[i] = uniqueLabels;
      } else {
        clusters[i] = uniqueLabels.first;
      }
    }
  }

  int iterations = 0;
  bool converged = false;
  while (iterations < 100 && !converged) {
    converged = true;
    for (int i = 0; i < points.length; i++) {
      if (clusters[i] == 0) continue;
      if (clusters[i].length >= 2) continue;

      List<int> neighbors = <int>[];
      for (int j = 0; j < points.length; j++) {
        if (distance(points[i], points[j]) <= eps) {
          neighbors.add(j);
        }
      }
      if (neighbors.length < minPts) {
        clusters[i] = 0;
      } else {
        Set<int> uniqueLabels = {};
        for (int neighbor in neighbors) {
          if (clusters[neighbor] != 0) {
            uniqueLabels.add(clusters[neighbor]);
          }
        }
        if (uniqueLabels.length > 1) {
          clusters[i] = uniqueLabels;
        } else {
          clusters[i] = uniqueLabels.first;
        }
      }
    }
    iterations++;
    if (iterations % 10 == 0) {
      print('Iteration $iterations: ${points.length} points, '
          '${clusters.length} clusters');
      for (int i = 0; i < points.length; i++) {
        print('  ${points[i]} -> ${clusters[i]}');
      }
    }
  }
  print('Converged in $iterations iteration(s).');

  for (int i = 0; i < points.length; i++) {
    print('Cluster ${clusters[i]}: ${points[i]}');
  }
}

