  ];

  double dist(List<double> a, List<double> b) => sqrt(pow(a[0] - b[0], 2) + pow(a[1] - b[1], 2));

  bool converged = false;
  int iteration = 0;

  while (!converged) {

    converged = true;

    for (int i = 0; i < centroids.length; i++) {

