          final double dx = newPoints[j] - centroids[i][0];
          final double dy = newPoints[j] - centroids[i][1];

          newPoints[j] = (newPoints[j] * (indices.length - 1) + dx) / indices.length;
          newLabels[j] = i;
        }
      }


      final double minDist = double.infinity;
      final int bestCluster = 0;

      for (int c = 0; c < k; c++) {
        if (c == i) continue;

        final double distToC = dist(newCentroid, centroids[c]);
