void fn0() {

  final rand = Random(0);

  final points = <List<double>>[
    [2, 3],
    [5, 4],
    [9, 6],
    [4, 7],
    [8, 1],
    [7, 2],
    [1, 5],
    [10, 3],
    [6, 8],
  ];

  int k = 3;
  final int n = points.length;

  double epsilone = 2;
  int minPts = 2;

  final visited = List.filled(n, false);

  final seed = List<int>.generate(n, (i) => i);

  double dist(List<double> a, List<double> b) {
    double sum = 0.0;
    for (int i = 0; i < a.length; i++) {
      final diff = a[i] - b[i];
      sum += diff * diff;
    }
    return sqrt(sum);
  }

  bool regionQuery(int idx, List<int> neighbors, List<List<double>> clusters) {

    final Set<int> neighborsSet = neighbors.toSet();
    bool hasMinPts = false;

    for (int i = 0; i < clusters.length; i++) {
      final List<double> center = clusters[i];
      if (neighborsSet.contains(i)) {
        if (center.length >= minPts) {
          hasMinPts = true;
          break;
        }
      }
    }

    if (!hasMinPts) return false;

    for (int i = 0; i < clusters.length; i++) {
      final List<double> center = clusters[i];
      if (center.length < minPts) continue;

      bool allCloseEnough = true;
      for (final point in points) {
        if (!neighborsSet.contains(i) &&
            dist(point, center) <= epsilone) {
          allCloseEnough = false;
          break;
        }
      }
      if (allCloseEnough) return true;
    }
    return false;
  }

  final clusters = <List<double>>[];

  while (seed.isNotEmpty) {
    final int idx = seed.removeLast();
    if (visited[idx]) continue;
    visited[idx] = true;

    final List<int> neighbors = <int>[];
    for (final p in points) {
      if (dist(p, points[idx]) <= epsilone) {
        neighbors.add(idx);
      }
    }

    if (regionQuery(idx, neighbors, clusters)) {

      clusters.add(points[idx]);

      for (final n in neighbors) {
        if (!seed.contains(n)) {
          seed.add(n);
        }
      }
    }
  }

  double dist2(List<double> a, List<double> b) {
    double sum = 0.0;
    for (int i = 0; i < a.length; i++) {
      final diff = a[i] - b[i];
      sum += diff * diff;
    }
    return sqrt(sum);
  }

  double mergeClusters(List<List<double>> clusters, List<int> idx1, List<int> idx2) {
    final List<double> center1 = clusters[idx1];
    final List<double> center2 = clusters[idx2];

    final newCenter = <double>[];
    for (int i = 0; i < center1.length; i++) {
      newCenter.add(center1[i]);
    }
    for (int i = 0; i < center2.length; i++) {
      newCenter.add(center2[i]);
    }

    double mergedDist = double.infinity;
    for (final p in points) {
      if (!newCenter.contains(p)) {
        final dist = dist2(p, newCenter);
        if (dist < mergedDist) mergedDist = dist;
      }
    }

    return mergedDist;
  }

  while (clusters.length > k) {
    double minDist = double.infinity;
    int idx1 = -1;
    int idx2 = -1;

    for (int i = 0; i < clusters.length; i++) {
      for (int j = i + 1; j < clusters.length; j++) {
        final dist = mergeClusters(clusters, i, j);
        if (dist < minDist) {
          minDist = dist;
          idx1 = i;
          idx2 = j;
        }
      }
    }

    if (idx1 == -1) break;

    final List<double> merged = <double>[];
    for (final p in clusters[idx1]) {
      merged.add(p);
    }
    for (final p in clusters[idx2]) {
      merged.add(p);
    }
    clusters.removeAt(idx1);
    clusters.removeAt(idx2);
    clusters.add(merged);
  }

