    }
    return sqrt(sum);
  }

  final List<List<double>> centroids = List<List<double>>.generate(k, (_) => List<double>.filled(data[0].length, 0.0));

  for (int i = 0; i < k; i++) {

    final int idx = rng.nextInt(n);
    for (int j = 0; j < data[idx].length; j++) {
      centroids[i][j] = data[idx][j];
    }
  }

  double distance(List<double> a, List<double> b) {
    double sum = 0.0;
    for (int i = 0; i < a.length; i++) {
      final diff = a[i] - b[i];
      sum += diff * diff;
    }
    return sqrt(sum);
  }

  double distance(List<double> a, List<double> b) {
    double sum = 0.0;
    for (int i = 0; i < a.length; i++) {
      final diff = a[i] - b[i];
      sum += diff * diff;
    }
    return sqrt(sum);
  }

  int centroidIdx(List<double> point) {
    int minIdx = 0;
    double minDist = distance(point, centroids[0]);
    for (int i = 1; i < k; i++) {
      final d = distance(point, centroids[i]);
      if (d < minDist) {
        minDist = d;
        minIdx = i;
      }
    }
    return minIdx;
  }

  int clusterIdx(List<double> point) {
    int cluster = centroidIdx(point);
    for (int i = 1; i < k; i++) {
      if (distance(point, centroids[i]) < distance(point, centroids[cluster])) {
        cluster = i;
      }
    }
    return cluster;
  }

