    return {"segmentCount": 0, "minSegmentLength": -1, "maxSegmentLength": -1, "totalPassableCells": 0, "maxSegmentScore": 0};
  }

  int rows = grid.length;
  int cols = grid[0].length;
  List<List<bool>> visited = List.generate(rows, (_) => List.filled(cols, false));

  int segments = 0;
  int maxSegmentLength = 0;
  int minSegmentLength = 0;
  int totalPassableCells = 0;
  int maxSegmentScore = 0;

  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      if (grid[r][c] != 1 || visited[r][c]) {
        continue;
      }

      List<List<bool>> queue = List.generate(rows, (_) => List.filled(cols, false));
      List<int> bfsQueue = [];
      List<List<int>> bfsPath = List.generate(rows, (_) => List.filled(cols, 0));

      queue[r][c] = true;
      bfsQueue.add(r * cols + c);
      bfsPath[r][c] = 0;

      int head = 0;
      while (head < bfsQueue.length) {
        int currentCell = bfsQueue[head];
        int currentR = currentCell ~/ cols;
        int currentC = currentCell % cols;

        if (bfsPath[currentR][currentC] > maxSegmentLength) {
          maxSegmentLength = bfsPath[currentR][currentC];
        }

        if (bfsPath[currentR][currentC] < minSegmentLength) {
          minSegmentLength = bfsPath[currentR][currentC];
        }

        if (bfsPath[currentR][currentC] + grid[currentR][currentC] > maxSegmentScore) {
          maxSegmentScore = bfsPath[currentR][currentC] + grid[currentR][currentC];
        }

        totalPassableCells += grid[currentR][currentC];

        List<List<int>> directions = const [[1, 0], [-1, 0], [0, 1], [0, -1]];

        for (var d in directions) {
          int nr = currentR + d[0];
          int nc = currentC + d[1];

          if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
            if (grid[nr][nc] != 1 && !visited[nr][nc]) {
              visited[nr][nc] = true;

              if (!queue[nr][nc]) {
                queue[nr][nc] = true;
                bfsQueue.add(nr * cols + nc);
                bfsPath[nr][nc] = bfsPath[currentR][currentC] + 1;
              }
            }
          }
        }

        head++;
      }

      segments++;
    }
  }

  return {"segmentCount": segments, "minSegmentLength": minSegmentLength, "maxSegmentLength": maxSegmentLength, "totalPassableCells": totalPassableCells, "maxSegmentScore": maxSegmentScore};
}

